 p=argparse.ArgumentParser();p.add_argument("--evaluation",type=Path,required=True);p.add_argument("--training-audit",type=Path,required=True);p.add_argument("--evaluation-audit",type=Path,required=True);p.add_argument("--cost-v2",type=Path,required=True);p.add_argument("--cost-m2",type=Path,required=True);p.add_argument("--cost-end-to-end-v2",type=Path,required=True);p.add_argument("--cost-end-to-end-m2",type=Path,required=True);p.add_argument("--supplement",type=Path,required=True);p.add_argument("--output",type=Path,required=True);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=True);(a.output/"figures").mkdir(exist_ok=True)
 ta=json.loads(a.training_audit.read_text());ea=json.loads(a.evaluation_audit.read_text());ev=json.loads((a.evaluation/"SUMMARY.json").read_text());cost={"V2":json.loads(a.cost_v2.read_text()),"M2":json.loads(a.cost_m2.read_text())};end_to_end={"V2":json.loads(a.cost_end_to_end_v2.read_text()),"M2":json.loads(a.cost_end_to_end_m2.read_text())};supplement=json.loads((a.supplement/"SUMMARY.json").read_text())
