 paucci=[x for x in ci if x["metric"]=="pAUC"];lines=["# Round 19 Q1B result","","All 24 V2/M2 runs completed under the locked two-block fine-tuning protocol; the unified evaluation reuses accepted V0/M0 predictions and never reads test.",""]
