 for g in groups:lines.append(f"- {g}: validation pAUC {headline[g]['pAUC']:.4f}, AP {headline[g]['AP']:.4f}, calibration-FPR5 transferred static FPR {headline[g]['frame_static_FPR']:.4f}, gross recall {headline[g]['gross_recall']:.4f}.")
